const CW = 'https://chat.miabuilder.com/api/v1/accounts/39';
const H = { api_access_token: 'SEPcKuFk5wqM67AsKE4FLPf6' };
const http = (o) => this.helpers.httpRequest({ json: true, ...o });
const importadas = new Set([1783,1817,1288,1189,2806,2740,2641,2509,2476,2443,2377,2278,1123,991,859,1024,430,1651,1552,1486,1453,1421,760,628,595,529,2872,2905,2971,2938,3004,1818,1948,1981,2113]);
const desde = Date.now() / 1000 - 6 * 3600;
const out = [];
for (const status of ['open', 'resolved']) {
  for (let page = 1; page <= 10; page++) {
    const r = await http({ method: 'GET', url: CW + '/conversations', headers: H, qs: { assignee_type: 'all', status, page, sort_by: 'last_activity_at_desc' } });
    const p = r?.data?.payload || [];
    for (const c of p) {
      if (importadas.has(c.id)) continue;
      if (status === 'resolved' && c.last_activity_at < desde) continue;
      const s = c.meta?.sender || {};
      out.push({ json: { status: c.status, conversa: c.id, inbox_id: c.inbox_id, nome: s.name, telefone: s.phone_number, atribuido: c.meta?.assignee?.name || null, ultima_atividade: new Date(c.last_activity_at * 1000).toISOString() } });
    }
    if (p.length < 25) break;
  }
}
return out.length ? out : [{ json: { nada: true } }];
